@Component({
  selector: 'app-root',
  imports: [
    RouterOutlet,
    RouterLink,
    RouterLinkActive,
    NgIcon,
    HlmIcon,
    HlmAvatarImports,
    HlmSidebarImports,
    HlmTypographyImports,
    AppTopbar,
  ],
  providers: [
    AppViewModel,
    provideIcons({
      lucideCrosshair,
      lucideLayoutDashboard,
      lucideSettings,
      lucideShieldAlert,
      lucideTarget,
      lucideUserPlus,
      lucideUsers,
    }),
  ],
  templateUrl: './app.html',
  styleUrl: './app.css',
})
export class App {
  protected readonly vm = inject(AppViewModel);
}
