  <nav aria-label="Breadcrumb" class="app-topbar__crumbs">
    <ol class="app-topbar__trail">
      @for (crumb of crumbs(); track $index; let first = $first, last = $last) {
        <li class="app-topbar__crumb" [attr.aria-current]="last ? 'page' : null">
