@reference "../../styles.css";

.dashboard { @apply grid content-start gap-8 p-6; }
.dashboard__header { @apply flex flex-wrap items-end justify-between gap-4; }
.dashboard__title { @apply grid gap-1; }
.dashboard__stats { @apply grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4; }
.dashboard__section { @apply grid gap-4; }
.dashboard__section-head { @apply flex flex-wrap items-center justify-between gap-3; }
.dashboard__heroes { @apply grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4; }

